+// Till sales: each sold dish consumes one portion of its recipe per qty,
+// with ledger ref "sale:<ticket>". Tickets already imported are skipped.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/**
+ * Records validated sale lines, consuming ingredients atomically and skipping
+ * tickets that were already imported. Returns { tickets, dishes } imported.
+ */
+export function recordSales(store, lines) {
+  const existing = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const fresh = lines.filter((l) => !existing.has(l.ticket));
+
+  // Simulate ingredient consumption across all new lines before mutating anything.
+  const remaining = new Map();
+  const plan = fresh.map((line) => {
+    const dish = getDish(store, line.dishId);
+    const recipe = getRecipe(store, dish.recipeId);
+    const needs = scaled(recipe, line.qty);
+    for (const n of needs) {
+      if (n.qty <= 0) continue;
+      const item = getItem(store, n.itemId);
+      const available = remaining.has(n.itemId) ? remaining.get(n.itemId) : round3(onHand(store, n.itemId));
+      if (available < n.qty) {
+        throw new AppError("not_enough_stock_row", { row: line.row, item: item.name, available, unit: item.unit });
+      }
+      remaining.set(n.itemId, round3(available - n.qty));
+    }
+    return { line, needs };
+  });
+
+  store.data.sales ??= [];
+  const tickets = new Set();
+  let dishes = 0;
+  for (const { line, needs } of plan) {
+    for (const n of needs) {
+      if (n.qty > 0) consume(store, n.itemId, n.qty, { at: line.soldAt, ref: `sale:${line.ticket}` });
+    }
+    store.data.sales.push({
+      id: store.nextId("sale"),
+      ticket: line.ticket,
+      soldAt: line.soldAt,
+      dishId: line.dishId,
+      qty: line.qty,
+    });
+    tickets.add(line.ticket);
+    dishes += line.qty;
+  }
+  return { tickets: tickets.size, dishes };
+}
