+++ b/src/io/sales-import.js
@@ -0,0 +1,37 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty).
+// The whole file is checked first; one bad row or stock shortage and nothing is imported.
+import { isIsoInstant } from "../dates.js";
+import { recordSales } from "../domain/sales.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+/** Imports till sales from CSV; returns { tickets, dishes } counts or throws naming the row. */
+export function importSales(store, text) {
+  const parsed = parseCsv(text);
+  if (!parsed.length) return { tickets: 0, dishes: 0 };
+  const [head, ...dataRows] = parsed;
+  const keys = head.map((h) => h.trim());
+  const missing = HEADER.find((k) => !keys.includes(k));
+  if (missing) {
+    const prefix = dataRows.length ? "row 2: " : "";
+    throw new AppError("bad_request", { reason: `${prefix}missing column ${missing}` });
+  }
+
+  const dishes = store.data.dishes ?? [];
+  const clean = dataRows.map((cells, i) => {
+    const where = `row ${i + 2}`;
+    const r = Object.fromEntries(keys.map((k, idx) => [k, (cells[idx] ?? "").trim()]));
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isIsoInstant(r.soldAt)) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    const dishId = Number(r.dishId);
+    if (!Number.isInteger(dishId) || dishId < 1) throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    if (!dishes.some((d) => d.id === dishId)) throw new AppError("bad_request", { reason: `${where}: unknown dish ${dishId}` });
+    const qty = Number(r.qty);
+    if (!Number.isInteger(qty) || qty < 1) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    return { row: where, ticket: r.ticket, soldAt: new Date(r.soldAt).toISOString(), dishId, qty };
+  });
+
+  return recordSales(store, clean);
+}
